def _encode_key(self, obj):
        """Encodes a dictionary key - a key can only be a string in std JSON"""
        if not isinstance(obj, basestring):
            raise TypeError(
                "dict keys must be strings: %r" % obj)
        return '"%s"' % obj.replace('\\', '\\\\').replace('"', r'\"')

